create table public.vacation_periods(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.employees(id) on delete cascade,acquisition_start date not null,acquisition_end date not null,concession_deadline date not null,earned_days integer not null default 30 check(earned_days>0),used_days integer not null default 0 check(used_days>=0),scheduled_days integer not null default 0 check(scheduled_days>=0),balance_days integer not null default 30 check(balance_days>=0),status text not null default 'open' check(status in('open','scheduled','completed','expired')),risk text not null default 'normal' check(risk in('normal','attention','critical')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(employee_id,acquisition_start));
create table public.vacation_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.employees(id) on delete cascade,period_id uuid not null references public.vacation_periods(id) on delete restrict,start_date date not null,end_date date not null,days integer not null check(days>0),sold_days integer not null default 0 check(sold_days between 0 and 10),advance_thirteenth boolean not null default false,status text not null default 'pending_manager' check(status in('pending_manager','pending_hr','approved','rejected','cancelled','completed')),requested_at timestamptz not null default now(),approved_at timestamptz,coverage_status text not null default 'pending' check(coverage_status in('pending','confirmed','not_required')),payroll_event_status text not null default 'pending' check(payroll_event_status in('pending','scheduled','processed')),note text,created_by uuid references auth.users(id),updated_at timestamptz not null default now(),check(end_date>=start_date));
create table public.medical_certificates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.employees(id) on delete cascade,start_date date not null,end_date date not null,days integer not null check(days>0),issuer text not null,professional_registration text not null,cid text,received_at timestamptz not null default now(),status text not null default 'under_review' check(status in('under_review','validated','rejected')),document_name text not null,validation_note text,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,check(end_date>=start_date));
create table public.absence_occurrences(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.employees(id) on delete cascade,type text not null check(type in('unjustified_absence','justified_absence','day_off','medical_certificate','leave')),start_date date not null,end_date date not null,days integer not null check(days>0),status text not null default 'pending' check(status in('pending','approved','rejected','active','closed')),reason text not null,impacts_time boolean not null default true,impacts_payroll boolean not null default false,document_id uuid references public.medical_certificates(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date>=start_date));
create table public.leave_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,employee_id uuid not null references public.employees(id) on delete cascade,type text not null check(type in('sickness','maternity','paternity','occupational_accident','unpaid','other')),start_date date not null,end_date date,days integer not null check(days>0),status text not null default 'scheduled' check(status in('scheduled','active','ended')),responsible text not null,return_forecast date not null,impacts_time boolean not null default true,impacts_payroll boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index vacation_periods_deadline_idx on public.vacation_periods(organization_id,concession_deadline);create index vacation_requests_employee_idx on public.vacation_requests(employee_id,requested_at desc);create index absence_occurrences_dates_idx on public.absence_occurrences(organization_id,start_date desc);create index medical_certificates_status_idx on public.medical_certificates(organization_id,status);create index leave_records_status_idx on public.leave_records(organization_id,status);
alter table public.vacation_periods enable row level security;alter table public.vacation_requests enable row level security;alter table public.medical_certificates enable row level security;alter table public.absence_occurrences enable row level security;alter table public.leave_records enable row level security;
revoke all on public.vacation_periods,public.vacation_requests,public.medical_certificates,public.absence_occurrences,public.leave_records from anon,authenticated;grant select on public.vacation_periods,public.vacation_requests,public.medical_certificates,public.absence_occurrences,public.leave_records to authenticated;
create policy vacation_periods_select on public.vacation_periods for select to authenticated using((select private.has_organization_role(organization_id,array['owner','admin','hr','manager','auditor']::public.organization_role[]))or exists(select 1 from public.employees e where e.id=employee_id and e.user_id=(select auth.uid())));create policy vacation_requests_select on public.vacation_requests for select to authenticated using((select private.has_organization_role(organization_id,array['owner','admin','hr','manager','auditor']::public.organization_role[]))or exists(select 1 from public.employees e where e.id=employee_id and e.user_id=(select auth.uid())));create policy medical_certificates_select on public.medical_certificates for select to authenticated using((select private.has_organization_role(organization_id,array['owner','admin','hr','manager','auditor']::public.organization_role[]))or exists(select 1 from public.employees e where e.id=employee_id and e.user_id=(select auth.uid())));create policy absence_occurrences_select on public.absence_occurrences for select to authenticated using((select private.has_organization_role(organization_id,array['owner','admin','hr','manager','auditor']::public.organization_role[]))or exists(select 1 from public.employees e where e.id=employee_id and e.user_id=(select auth.uid())));create policy leave_records_select on public.leave_records for select to authenticated using((select private.has_organization_role(organization_id,array['owner','admin','hr','manager','auditor']::public.organization_role[]))or exists(select 1 from public.employees e where e.id=employee_id and e.user_id=(select auth.uid())));
create or replace function public.create_vacation_request(employee_id_value uuid,period_id_value uuid,start_date_value date,end_date_value date,sold_days_value integer,advance_thirteenth_value boolean,note_value text default null)returns uuid language plpgsql security definer set search_path='' as $$declare organization_id_value uuid;balance_value integer;days_value integer;request_id_value uuid;begin select organization_id,balance_days into organization_id_value,balance_value from public.vacation_periods where id=period_id_value and employee_id=employee_id_value for update;if organization_id_value is null then raise exception 'period_not_found' using errcode='P0002';end if;if not(private.has_organization_role(organization_id_value,array['owner','admin','hr','manager']::public.organization_role[])or exists(select 1 from public.employees where id=employee_id_value and user_id=(select auth.uid())))then raise exception 'vacation_request_forbidden' using errcode='42501';end if;days_value=end_date_value-start_date_value+1;if days_value<=0 then raise exception 'invalid_period' using errcode='22023';end if;if sold_days_value<0 or sold_days_value>10 or days_value+sold_days_value>balance_value then raise exception 'insufficient_balance' using errcode='22023';end if;insert into public.vacation_requests(organization_id,employee_id,period_id,start_date,end_date,days,sold_days,advance_thirteenth,note,created_by)values(organization_id_value,employee_id_value,period_id_value,start_date_value,end_date_value,days_value,sold_days_value,advance_thirteenth_value,note_value,(select auth.uid()))returning id into request_id_value;update public.vacation_periods set scheduled_days=scheduled_days+days_value+sold_days_value,balance_days=balance_days-days_value-sold_days_value,status='scheduled',updated_at=now()where id=period_id_value;insert into public.domain_events(organization_id,aggregate_type,aggregate_id,event_type,payload)values(organization_id_value,'vacation_request',request_id_value,'vacation.requested',jsonb_build_object('employeeId',employee_id_value,'days',days_value,'soldDays',sold_days_value));return request_id_value;end;$$;
create or replace function public.decide_vacation_request(request_id_value uuid,decision_value text,note_value text)returns void language plpgsql security definer set search_path='' as $$declare organization_id_value uuid;before_value jsonb;period_id_value uuid;reserved_days integer;begin select organization_id,to_jsonb(r),period_id,days+sold_days into organization_id_value,before_value,period_id_value,reserved_days from public.vacation_requests r where id=request_id_value for update;if organization_id_value is null then raise exception 'request_not_found' using errcode='P0002';end if;if not private.has_organization_role(organization_id_value,array['owner','admin','hr','manager']::public.organization_role[])then raise exception 'vacation_decision_forbidden' using errcode='42501';end if;if decision_value not in('approve','reject')or length(trim(coalesce(note_value,'')))<3 then raise exception 'invalid_decision' using errcode='22023';end if;update public.vacation_requests set status=case when decision_value='approve'then'approved'else'rejected'end,approved_at=case when decision_value='approve'then now()else null end,payroll_event_status=case when decision_value='approve'then'scheduled'else'pending'end,note=trim(note_value),updated_at=now()where id=request_id_value;if decision_value='reject'then update public.vacation_periods set scheduled_days=greatest(0,scheduled_days-reserved_days),balance_days=balance_days+reserved_days,status=case when scheduled_days-reserved_days<=0 then'open'else status end,updated_at=now()where id=period_id_value;end if;insert into public.audit_events(organization_id,actor_type,actor_id,action,resource_type,resource_id,before_data,after_data)values(organization_id_value,'user',(select auth.uid()),'vacation.'||decision_value,'vacation_request',request_id_value::text,before_value,(select to_jsonb(r)from public.vacation_requests r where id=request_id_value));end;$$;
create or replace function public.create_medical_certificate(employee_id_value uuid,start_date_value date,end_date_value date,issuer_value text,registration_value text,cid_value text,document_name_value text)returns uuid language plpgsql security definer set search_path='' as $$declare organization_id_value uuid;days_value integer;certificate_id_value uuid;begin select organization_id into organization_id_value from public.employees where id=employee_id_value;if organization_id_value is null then raise exception 'employee_not_found' using errcode='P0002';end if;if not(private.has_organization_role(organization_id_value,array['owner','admin','hr','manager']::public.organization_role[])or exists(select 1 from public.employees where id=employee_id_value and user_id=(select auth.uid())))then raise exception 'certificate_create_forbidden' using errcode='42501';end if;days_value=end_date_value-start_date_value+1;if days_value<=0 then raise exception 'invalid_period' using errcode='22023';end if;insert into public.medical_certificates(organization_id,employee_id,start_date,end_date,days,issuer,professional_registration,cid,document_name)values(organization_id_value,employee_id_value,start_date_value,end_date_value,days_value,issuer_value,registration_value,cid_value,document_name_value)returning id into certificate_id_value;insert into public.absence_occurrences(organization_id,employee_id,type,start_date,end_date,days,status,reason,impacts_time,impacts_payroll,document_id)values(organization_id_value,employee_id_value,'medical_certificate',start_date_value,end_date_value,days_value,'pending','Aguardando validação do atestado',true,false,certificate_id_value);insert into public.domain_events(organization_id,aggregate_type,aggregate_id,event_type,payload)values(organization_id_value,'medical_certificate',certificate_id_value,'absence.certificate_received',jsonb_build_object('employeeId',employee_id_value,'days',days_value));return certificate_id_value;end;$$;
create or replace function public.review_medical_certificate(certificate_id_value uuid,decision_value text,note_value text)returns void language plpgsql security definer set search_path='' as $$declare organization_id_value uuid;before_value jsonb;begin select organization_id,to_jsonb(c)into organization_id_value,before_value from public.medical_certificates c where id=certificate_id_value for update;if organization_id_value is null then raise exception 'certificate_not_found' using errcode='P0002';end if;if not private.has_organization_role(organization_id_value,array['owner','admin','hr']::public.organization_role[])then raise exception 'certificate_review_forbidden' using errcode='42501';end if;if decision_value not in('approve','reject')or length(trim(coalesce(note_value,'')))<3 then raise exception 'invalid_decision' using errcode='22023';end if;update public.medical_certificates set status=case when decision_value='approve'then'validated'else'rejected'end,validation_note=trim(note_value),reviewed_by=(select auth.uid()),reviewed_at=now()where id=certificate_id_value;update public.absence_occurrences set status=case when decision_value='approve'then'approved'else'rejected'end,updated_at=now()where document_id=certificate_id_value;insert into public.audit_events(organization_id,actor_type,actor_id,action,resource_type,resource_id,before_data,after_data)values(organization_id_value,'user',(select auth.uid()),'certificate.'||decision_value,'medical_certificate',certificate_id_value::text,before_value,(select to_jsonb(c)from public.medical_certificates c where id=certificate_id_value));end;$$;
revoke all on function public.create_vacation_request(uuid,uuid,date,date,integer,boolean,text),public.decide_vacation_request(uuid,text,text),public.create_medical_certificate(uuid,date,date,text,text,text,text),public.review_medical_certificate(uuid,text,text)from public,anon;grant execute on function public.create_vacation_request(uuid,uuid,date,date,integer,boolean,text),public.decide_vacation_request(uuid,text,text),public.create_medical_certificate(uuid,date,date,text,text,text,text),public.review_medical_certificate(uuid,text,text)to authenticated;
